Source code in <code>showco/deployment/card.py</code> <pre><code>def mounted_user_data_path(value: dict[str, object]) -&gt; Path | None:
    partitions = value.get('Partitions', [])
    if not isinstance(partitions, list):
        return None
    for partition in partitions:
        if not is_dictionary(partition):
            continue
        mount_point = partition.get('MountPoint')
        if not isinstance(mount_point, str):
            continue
        if (path := Path(mount_point) / 'user-data').is_file():
            return path
    return None
