Source code in <code>showco/deployment/local_update.py</code> <pre><code>def locked_dependency_sources(
    program: update.Program, dependencies: list[str]
) -&gt; dict[str, str]:
    data = tomllib.loads((program.directory / 'uv.lock').read_text())
    packages = data.get('package', [])
    if not isinstance(packages, list):
        return {}
    result = {}
    for package in packages:
        if not isinstance(package, dict):
            continue
        name = package.get('name')
        source = package.get('source')
        if (
            isinstance(name, str)
            and name in dependencies
            and isinstance(source, dict)
            and isinstance(git := source.get('git'), str)
        ):
            result[name] = git
    return result
