Source code in <code>showco/deployment/report_scan.py</code> <pre><code>def recording_sessions(roots: list[Path], limitations: list[str]) -&gt; list[Session]:
    directories: set[Path] = set()

    def unreadable(error: OSError) -&gt; None:
        limitations.append(f'Cannot scan recordings: {safe_message(str(error))}')

    for root in roots:
        for directory, _, files in os.walk(root, onerror=unreadable):
            if 'session-record.jsonl' in files:
                directories.add(Path(directory).resolve())
    sessions: list[Session] = []
    for path in sorted(directories):
        try:
