Source code in <code>showco/deployment/update.py</code> <pre><code>def run_service_step(
    service_name: str,
    step: str,
    run_command: RunCommand,
    *,
    executable: Path | None = None,
) -&gt; StepResult:
    spec = services.SERVICES[service_name]
    command = ['systemctl', '--user', step, spec.systemd_unit]
    try:
        controller = services.service_registry(
            runner=service_runner(run_command)
        ).controller(service_name)
        if step == 'stop':
            controller.stop()
        elif step == 'start':
            controller.start()
        elif step == 'refresh':
            result = services.refresh_service_definition(
                service_name,
                runner=service_runner(run_command),
                executable=executable,
            )
        else:
            return StepResult(
                program=service_name,
                step=step,
                command=command,
                returncode=2,
                output=f'unsupported service step {step}',
            )
        if step != 'refresh':
            result = controller.status()
    except FileNotFoundError as e:
        return StepResult(
            program=service_name,
            step=step,
            command=command,
            returncode=127,
            output=str(e),
        )
    except CalledProcessError as e:
        return StepResult(
            program=service_name,
            step=step,
            command=list(e.cmd),
            returncode=e.returncode,
            output=f'{e.stdout or ""}{e.stderr or ""}',
        )
    except TimeoutExpired as e:
        return StepResult(
            program=service_name,
            step=step,
            command=command,
            returncode=124,
            output=timeout_output(e),
        )
    return StepResult(
        program=service_name,
        step=step,
        command=command,
        returncode=0,
        output=result.details,
    )
