    program: str, step: str, command: list[str], run_command: RunCommand
) -&gt; StepResult:
    try:
        completed = run_command(command)
    except OSError as e:
        return StepResult(
            program=program,
            step=step,
            command=command,
            returncode=127,
            output=str(e),
        )
    except TimeoutExpired as e:
        return StepResult(
            program=program,
            step=step,
            command=command,
            returncode=124,
