Source code in <code>showco/provision/network.py</code> <pre><code>def split_nmcli_terse_fields(line: str) -&gt; list[str]:
    fields: list[str] = []
    current: list[str] = []
    escaped = False
    for c in line:
        if escaped:
            current.append(c)
            escaped = False
        elif c == '\\':
            escaped = True
        elif c == ':':
            fields.append(''.join(current))
            current = []
        else:
            current.append(c)
    if escaped:
        current.append('\\')
    fields.append(''.join(current))
    return fields
