Source code in <code>showco/provision/ssh.py</code> <pre><code>def run_command(
    command: list[str],
    *,
    capture_output: bool = False,
    timeout_seconds: int | None = None,
) -&gt; CompletedProcess[str]:
    if not capture_output:
        process = Popen(
            command,
            stdout=PIPE,
            stderr=STDOUT,
            start_new_session=True,
        )
        assert process.stdout is not None
        returncode = None
        with (
            TextIOWrapper(process.stdout, newline='') as stream,
            tempfile.TemporaryFile(mode='w+t', newline='') as record,
            tqdm(
                desc='Running remote command',
                bar_format='{desc} [{elapsed}]',
                file=sys.stdout,
                disable=not sys.stdout.isatty(),
                leave=False,
            ) as progress,
        ):

            def collect_output() -&gt; None:
                for line in stream:
                    record.write(line)
                    if line.startswith('==&gt; '):
                        progress.set_description_str(line[4:].strip())

            reader = Thread(target=collect_output, daemon=True)
            reader.start()
            try:
                returncode = process.wait(timeout=timeout_seconds)
            finally:
                reader.join(timeout=0 if process.poll() is None else 1)
                if process.poll() is None or reader.is_alive():
                    try:
                        os.killpg(process.pid, signal.SIGKILL)
                    except ProcessLookupError:
                        pass
                    process.wait()
                    reader.join(timeout=1)
                if reader.is_alive():
                    raise TimeoutError(
                        'Command output did not close after process group termination'
                    )
                progress.close()
                if returncode != 0:
                    record.flush()
                    record.seek(0)
                    shutil.copyfileobj(record, sys.stdout)
                    sys.stdout.flush()
        if returncode != 0:
            raise CalledProcessError(returncode, command)
        return CompletedProcess(command, returncode)
    if timeout_seconds is None:
        return cast(
            CompletedProcess[str],
            subprocess.run(
                command,
                capture_output=capture_output,
                check=True,
                text=True,
            ),
        )
    return cast(
        CompletedProcess[str],
        subprocess.run(
            command,
            capture_output=capture_output,
            check=True,
            text=True,
            timeout=timeout_seconds,
        ),
    )
</code></pre>

