    def call(
        self,
        command: str,
        parameters: dict[str, object] | None = None,
        *,
        timeout: float | None = None,
    ) -&gt; object:
        if timeout is None:
            timeout = 21.0 if command == 'calibrate' else CONTROL_TIMEOUT_SECONDS
