            if sys.platform == 'linux' and self.control_endpoint == default_endpoint:
                try:
                    service = controller.ServiceController(
                        STREAMO_SERVICE, paths.current_platform()
                    ).status()
                except (OSError, subprocess.SubprocessError, ValueError):
                    pass
                else:
                    if (
                        service.installed
                        and service.running is False
                        and service.details == 'inactive'
                    ):
                        return StreamoStatus(
                            service=ServiceStatus(name='streamo', state='connected'),
                            stream_state='stopped',
                        )
            last_failure = None
            if self.control_endpoint == default_endpoint:
                try:
                    saved = ReccyStatus.model_validate_json(
                        service_paths.status.read_bytes()
                    )
                except (OSError, ValueError):
                    pass
                else:
                    if not saved.running and saved.errors:
                        last_failure = (
                            f'Last streamO failure: {saved.errors[-1].message}'
                        )
            return StreamoStatus(
                service=ServiceStatus(
                    name='streamo',
                    state='offline',
                    last_error=(
                        last_failure
                        or (
                            f'streamO is not responding: its control socket '
                            f'{self.control_endpoint} does not exist. The service may '
                            'not be running or may have failed during startup. '
                            'Check the streamO service log for the cause.'
                            if isinstance(error, FileNotFoundError)
                            else str(error)
                        )
                    ),
                )
            )
        if not isinstance(status, dict):
            return StreamoStatus(
                service=ServiceStatus(
                    name='streamo',
                    state='error',
                    last_error='streamo status reply is not an object',
                )
            )
        stream_state = _string(status.get('state'))
        if stream_state not in {
            'stopped',
            'starting',
            'publishing',
            'streaming',
            'muted',
            'stopping',
            'failed',
        }:
            return StreamoStatus(
                service=ServiceStatus(
                    name='streamo',
                    state='error',
                    last_error='streamO status reply has invalid state',
                )
            )
        assert stream_state is not None
        last_error = _health_error(status, stream_state)
        service_state = 'error' if last_error else 'connected'
        return StreamoStatus(
            service=ServiceStatus(
                name='streamo',
                state=service_state,
                last_error=last_error,
            ),
            stream_state=stream_state,
            streaming_service=_string(status.get('service')),
            endpoint_host=_string(status.get('endpoint_host')),
            capabilities=_strings(status.get('capabilities')),
            remote_health=_dictionary(status.get('remote_health')),
            muted=bool(status.get('muted')),
            ffmpeg_alive=bool(status.get('ffmpeg_alive')),
            audio_seconds=_float(status.get('audio_seconds')),
            last_audio_at=_float(status.get('last_audio_at')),
            clipping=bool(status.get('clipping')),
            output_bitrate_kbps=_float(status.get('output_bitrate_kbps')),
            closing=_closing(status.get('closing')),
        )

    def start_closing(self, operation_id: str) -&gt; str:
        result = self._call('close_start', operation_id=operation_id)
        if not isinstance(result, dict) or result.get('operation_id') != operation_id:
            raise ValueError('streamO sent an invalid close_start response')
        return operation_id

    def action(self, command: str, **fields: object) -&gt; ActionResult:
        try:
            result = self._call(command, **fields)
        except (
            rpc.RemoteError,
            ConnectionError,
            OSError,
            TimeoutError,
            ValueError,
        ) as error:
            return ActionResult(
                ok=False,
                message=str(error),
            )
        if command in LOCAL_ACTIONS and result == 'ok':
            return ActionResult(ok=True, message=f'streamo {command} succeeded')
        if command in STREAM_API_ACTIONS and isinstance(result, dict):
            return ActionResult(ok=True, message=f'streamo {command} succeeded')
        return ActionResult(
            ok=False,
            message=f'streamo sent an invalid {command} response',
        )

    def _call(self, command: str, **fields: object) -&gt; object:
        return rpc.Client(self.control_endpoint, role='showco').call(command, **fields)
