Source code in <code>showco/x18/cable_test.py</code> <pre><code>def parse_range(value: str, minimum: int, maximum: int, name: str) -&gt; list[int]:
    parts = value.split('-')
    if len(parts) not in {1, 2}:
        raise ValueError(f'{name} must be N or N-M')
    try:
        first = int(parts[0])
        last = int(parts[-1])
    except ValueError:
        raise ValueError(f'{name} must be N or N-M') from None
    if first &gt; last:
        raise ValueError(f'{name} range must be ascending')
    if first &lt; minimum or last &gt; maximum:
        raise ValueError(f'{name} must be within {minimum}-{maximum}')
    return list(range(first, last + 1))
